    18	public final class Main {
    19	    /** Taxa de turismo por hóspede por noite; a prefeitura muda todo ano. */
    20	    private static final BigDecimal TOURISM_TAX = new BigDecimal("4.50");
    21	
    22	    public static void main(String[] args) {
    23	        DataSource ds = Database.connect(required("DB_URL"), System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
