     9	import io.javalin.Javalin;
    10	import io.javalin.http.Context;
    11	import io.javalin.json.JavalinJackson;
    12	import pousada.domain.AppException;
    13	import pousada.domain.Reservation;
    14	import pousada.domain.RoomCatalog;
    15	import pousada.repo.MessageRepository;
    16	import pousada.reports.Report;
    17	import pousada.service.NewReservation;
    18	import pousada.service.ReservationService;
    19	
    20	import java.math.BigDecimal;
    21	import java.time.LocalDate;
    22	import java.util.List;
    23	import java.util.Map;
    24	
    25	public final class Api {
    26	    private Api() {
    27	    }
    28	
    29	    public record RoomView(int number, String type, int capacity, BigDecimal nightlyRate) {
    30	    }
    31	
    32	    public record ReservationView(long id, int roomNumber, String guestName, String guestEmail, String guestCpf,
    33	                                  LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan, int nights,
    34	                                  BigDecimal subtotal, BigDecimal discount, BigDecimal total, String status,
    35	                                  BigDecimal amountPaid, BigDecimal refund) {
    36	        static ReservationView of(Reservation r) {
    37	            return new ReservationView(r.id(), r.roomNumber(), r.guestName(), r.guestEmail(), r.guestCpf(),
    38	                    r.checkIn(), r.checkOut(), r.guests(), r.ratePlan().name(), r.nights(), r.subtotal(),
    39	                    r.discount(), r.total(), r.status().name(), r.amountPaid(), r.refund());
    40	        }
    41	    }
    42	
    43	    /** Monta o servidor; cada relatório novo entra só na lista {@code reports}. */
    44	    public static Javalin create(ReservationService service, MessageRepository messages, List<Report<?>> reports) {
    45	        ObjectMapper mapper = new ObjectMapper()
    46	                .registerModule(new JavaTimeModule())
    47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    48	                .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
    49	        Javalin app = Javalin.create(cfg -> cfg.jsonMapper(new JavalinJackson(mapper, false)));
    50	
    51	        app.get("/rooms", ctx -> ctx.json(RoomCatalog.all().stream()
    52	                .map(r -> new RoomView(r.number(), r.type().name(), r.capacity(), r.nightlyRate())).toList()));
    53	
    54	        app.post("/reservations", ctx -> {
    55	            JsonNode body;
    56	            try {
    57	                body = mapper.readTree(ctx.body());
    58	            } catch (JsonProcessingException e) {
    59	                throw AppException.invalid("O corpo não é um JSON válido");
    60	            }
    61	            ctx.status(201).json(ReservationView.of(service.create(NewReservation.parse(body))));
    62	        });
    63	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationView.of(service.get(id(ctx)))));
    64	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(ReservationView.of(service.confirm(id(ctx)))));
    65	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(ReservationView.of(service.cancel(id(ctx)))));
    66	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(ReservationView.of(service.checkIn(id(ctx)))));
    67	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
    68	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.receipt(id(ctx))));
    69	        app.get("/messages", ctx -> ctx.json(messages.all()));
    70	
    71	        for (Report<?> report : reports) {
    72	            app.get("/reports/" + report.name(), ctx -> {
    73	                String period = ctx.queryParam(report.periodParam());
    74	                if (period == null) {
    75	                    throw AppException.invalid("Falta o parâmetro " + report.periodParam());
    76	                }
    77	                ctx.contentType("text/csv; charset=utf-8").result(report.render(period));
    78	            });
    79	        }
    80	
    81	        app.exception(AppException.class, (e, ctx) ->
    82	                ctx.status(e.status()).json(Map.of("error", e.code(), "message", e.getMessage())));
    83	        app.exception(Exception.class, (e, ctx) -> {
    84	            e.printStackTrace();
    85	            ctx.status(500).json(Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    86	        });
    87	        return app;
    88	    }
    89	
    90	    private static long id(Context ctx) {
    91	        try {
    92	            return Long.parseLong(ctx.pathParam("id"));
    93	        } catch (NumberFormatException e) {
    94	            throw new AppException(404, "RESERVATION_NOT_FOUND", "Reserva não existe");
    95	        }
    96	    }
    97	}
