=== src/main/java/pousada/service/NewReservation.java
     1	package pousada.service;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	import pousada.domain.AppException;
     5	import pousada.domain.RatePlan;
     6	
     7	import java.time.LocalDate;
     8	import java.time.format.DateTimeParseException;
     9	
    10	public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    11	                             LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    12	
    13	    public static NewReservation parse(JsonNode body) {
    14	        if (body == null || !body.isObject()) {
    15	            throw AppException.invalid("O corpo deve ser um objeto JSON");
    16	        }
    17	        LocalDate checkIn = date(body, "checkIn");
    18	        LocalDate checkOut = date(body, "checkOut");
    19	        if (!checkOut.isAfter(checkIn)) {
    20	            throw AppException.invalid("A saída deve ser depois da entrada");
    21	        }
    22	        int guests = integer(body, "guests");
    23	        if (guests < 1) {
    24	            throw AppException.invalid("É preciso pelo menos um hóspede");
    25	        }
    26	        RatePlan plan;
    27	        try {
    28	            plan = RatePlan.valueOf(text(body, "ratePlan"));
    29	        } catch (IllegalArgumentException e) {
    30	            throw AppException.invalid("ratePlan inválido");
    31	        }
    32	        return new NewReservation(integer(body, "roomNumber"), text(body, "guestName"), text(body, "guestEmail"),
    33	                text(body, "guestCpf"), checkIn, checkOut, guests, plan);
    34	    }
    35	
    36	    private static String text(JsonNode body, String field) {
    37	        JsonNode n = body.get(field);
    38	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
    39	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
    40	        }
    41	        return n.asText();
    42	    }
    43	
    44	    private static int integer(JsonNode body, String field) {
    45	        JsonNode n = body.get(field);
    46	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
    47	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
    48	        }
    49	        return n.asInt();
    50	    }
    51	
    52	    private static LocalDate date(JsonNode body, String field) {
    53	        try {
    54	            return LocalDate.parse(text(body, field));
    55	        } catch (DateTimeParseException e) {
    56	            throw AppException.invalid("Data inválida em " + field);
    57	        }
    58	    }
    59	}
=== src/main/java/pousada/service/ReservationService.java
     1	package pousada.service;
     2	
     3	import pousada.domain.AppException;
     4	import pousada.domain.Receipt;
     5	import pousada.domain.Reservation;
     6	import pousada.domain.Room;
     7	import pousada.domain.RoomCatalog;
     8	import pousada.repo.ReservationRepository;
     9	
    10	public class ReservationService {
    11	    private final ReservationRepository reservations;
    12	    private final ConfirmationMailer mailer;
    13	
    14	    public ReservationService(ReservationRepository reservations, ConfirmationMailer mailer) {
    15	        this.reservations = reservations;
    16	        this.mailer = mailer;
    17	    }
    18	
    19	    public synchronized Reservation create(NewReservation req) {
    20	        Room room = RoomCatalog.require(req.roomNumber());
    21	        if (req.guests() > room.capacity()) {
    22	            throw new AppException(422, "CAPACITY_EXCEEDED",
    23	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    24	        }
    25	        if (reservations.hasOverlap(room.number(), req.checkIn(), req.checkOut())) {
    26	            throw new AppException(409, "ROOM_UNAVAILABLE", "O quarto já está reservado em alguma dessas noites");
    27	        }
    28	        return reservations.insert(Reservation.pending(room, req.guestName(), req.guestEmail(), req.guestCpf(),
    29	                req.checkIn(), req.checkOut(), req.guests(), req.ratePlan()));
    30	    }
    31	
    32	    public Reservation get(long id) {
    33	        return reservations.find(id).orElseThrow(() ->
    34	                new AppException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe"));
    35	    }
    36	
    37	    public synchronized Reservation confirm(long id) {
    38	        Reservation r = get(id);
    39	        r.confirm();
    40	        reservations.update(r);
    41	        mailer.send(r);
    42	        return r;
    43	    }
    44	
    45	    public synchronized Reservation checkIn(long id) {
    46	        Reservation r = get(id);
    47	        r.doCheckIn();
    48	        reservations.update(r);
    49	        return r;
    50	    }
    51	
    52	    public synchronized Receipt checkOut(long id) {
    53	        Reservation r = get(id);
    54	        r.doCheckOut();
    55	        reservations.update(r);
    56	        return Receipt.of(r);
    57	    }
    58	
    59	    public synchronized Reservation cancel(long id) {
    60	        Reservation r = get(id);
    61	        r.cancel();
    62	        reservations.update(r);
    63	        return r;
    64	    }
    65	
    66	    /** Segunda via: só existe para reserva paga. */
    67	    public Receipt receipt(long id) {
    68	        Reservation r = get(id);
    69	        if (!r.status().isPaid()) {
    70	            throw AppException.notAllowed("Só uma reserva paga tem comprovante");
    71	        }
    72	        return Receipt.of(r);
    73	    }
    74	}

