    11	                             LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    12	
    13	    public static NewReservation parse(JsonNode body) {
    14	        if (body == null || !body.isObject()) {
    15	            throw AppException.invalid("O corpo deve ser um objeto JSON");
    16	        }
    17	        LocalDate checkIn = date(body, "checkIn");
    18	        LocalDate checkOut = date(body, "checkOut");
    19	        if (!checkOut.isAfter(checkIn)) {
    20	            throw AppException.invalid("A saída deve ser depois da entrada");
    21	        }
    22	        int guests = integer(body, "guests");
    23	        if (guests < 1) {
    24	            throw AppException.invalid("É preciso pelo menos um hóspede");
    25	        }
    26	        RatePlan plan;
    27	        try {
    28	            plan = RatePlan.valueOf(text(body, "ratePlan"));
    29	        } catch (IllegalArgumentException e) {
    30	            throw AppException.invalid("ratePlan inválido");
    31	        }
    32	        return new NewReservation(integer(body, "roomNumber"), text(body, "guestName"), text(body, "guestEmail"),
    33	                text(body, "guestCpf"), checkIn, checkOut, guests, plan);
    34	    }
    35	
    36	    private static String text(JsonNode body, String field) {
    37	        JsonNode n = body.get(field);
    38	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
    39	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
    40	        }
    41	        return n.asText();
    42	    }
    43	
    44	    private static int integer(JsonNode body, String field) {
    45	        JsonNode n = body.get(field);
    46	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
    47	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
    48	        }
    49	        return n.asInt();
    50	    }
    51	
    52	    private static LocalDate date(JsonNode body, String field) {
    53	        try {
    54	            return LocalDate.parse(text(body, field));
    55	        } catch (DateTimeParseException e) {
    56	            throw AppException.invalid("Data inválida em " + field);
    57	        }
    58	    }
    59	}
