    18	
    19	    public synchronized Reservation create(NewReservation req) {
    20	        Room room = RoomCatalog.require(req.roomNumber());
    21	        if (req.guests() > room.capacity()) {
    22	            throw new AppException(422, "CAPACITY_EXCEEDED",
    23	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    24	        }
    25	        if (reservations.hasOverlap(room.number(), req.checkIn(), req.checkOut())) {
    26	            throw new AppException(409, "ROOM_UNAVAILABLE", "O quarto já está reservado em alguma dessas noites");
    27	        }
    28	        return reservations.insert(Reservation.pending(room, req.guestName(), req.guestEmail(), req.guestCpf(),
    29	                req.checkIn(), req.checkOut(), req.guests(), req.ratePlan()));
    30	    }
