     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	public final class Pricing {
     9	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    10	
    11	    private Pricing() {
    12	    }
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    15	    }
    16	
    17	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    18	    public static boolean isHighSeason(LocalDate night) {
    19	        Month month = night.getMonth();
    20	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    21	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    22	    }
    23	
    24	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    25	        BigDecimal rate = room.nightlyRate();
    26	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    27	    }
    28	
    29	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    30	        BigDecimal subtotal = Money.ZERO;
    31	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    32	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    33	        }
    34	        BigDecimal discount = plan.discountOn(subtotal);
    35	        BigDecimal total = Money.round(subtotal.subtract(discount));
    36	        return new Quote((int) ChronoUnit.DAYS.between(checkIn, checkOut), subtotal, discount, total);
    37	    }
    38	}
