     8	/**
     9	 * Esqueleto de todo relatório CSV: título, cabeçalho, linhas e total.
    10	 * Cada relatório só diz o que é dele; qualquer mudança no formato comum entra em {@link #render}.
    11	 */
    12	public abstract class Report<P> {
    13	    public static final String HOUSE = "Pousada Maré Alta";
    14	
    15	    public record Body(List<String> rows, String total) {
    16	    }
    17	
    18	    /** Nome no título e na URL. */
    19	    public abstract String name();
    20	
    21	    /** Parâmetro de consulta que traz o período. */
    22	    public abstract String periodParam();
    23	
    24	    protected abstract P parsePeriod(String raw);
    25	
    26	    protected abstract String header();
    27	
    28	    protected abstract Body body(P period);
    29	
    30	    protected String periodText(P period) {
    31	        return period.toString();
    32	    }
    33	
    34	    public final String render(String rawPeriod) {
    35	        P period;
    36	        try {
    37	            period = parsePeriod(rawPeriod);
    38	        } catch (java.time.format.DateTimeParseException e) {
    39	            throw AppException.invalid("Período inválido em " + periodParam());
    40	        }
    41	        Body body = body(period);
    42	        List<String> lines = new ArrayList<>();
    43	        lines.add(String.join(",", HOUSE, name(), periodText(period)));
    44	        lines.add(header());
    45	        lines.addAll(body.rows());
    46	        lines.add(body.total());
    47	        return String.join("\n", lines) + "\n";
    48	    }
    49	}
