    70	        String sql = "SELECT 1 FROM reservations WHERE room_number=? AND status<>'CANCELLED'"
    71	                + " AND check_in < ? AND check_out > ? LIMIT 1";
    72	        try (Connection c = ds.getConnection(); PreparedStatement ps = c.prepareStatement(sql)) {
    73	            ps.setInt(1, roomNumber);
    74	            ps.setDate(2, Date.valueOf(checkOut));
    75	            ps.setDate(3, Date.valueOf(checkIn));
    76	            try (ResultSet rs = ps.executeQuery()) {
    77	                return rs.next();
    78	            }
