  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import io.javalin.Javalin;
  6	import org.junit.jupiter.api.AfterEach;
  7	import org.junit.jupiter.api.BeforeEach;
  8	import org.junit.jupiter.api.Test;
  9	import pousada.domain.Money;
 10	import pousada.domain.Pricing;
 11	import pousada.domain.RoomCatalog;
 12	import pousada.domain.RatePlan;
 13	import pousada.repo.InMemoryMessageRepository;
 14	import pousada.repo.InMemoryReservationRepository;
 15	import pousada.reports.OccupancyReport;
 16	import pousada.reports.RatePlanReport;
 17	import pousada.reports.Report;
 18	import pousada.reports.RevenueReport;
 19	import pousada.reports.TourismTaxReport;
 20	import pousada.service.ConfirmationMailer;
 21	import pousada.service.ReservationService;
 22	import pousada.web.Api;
 23	
 24	import java.math.BigDecimal;
 25	import java.net.URI;
 26	import java.net.http.HttpClient;
 27	import java.net.http.HttpRequest;
 28	import java.net.http.HttpResponse;
 29	import java.time.LocalDate;
 30	import java.util.List;
 31	
 32	import static org.junit.jupiter.api.Assertions.assertEquals;
 33	import static org.junit.jupiter.api.Assertions.assertTrue;
 34	
 35	class PousadaTest {
 36	    private final ObjectMapper json = new ObjectMapper();
 37	    private final HttpClient http = HttpClient.newHttpClient();
 38	    private Javalin app;
 39	    private String base;
 40	
 41	    @BeforeEach
 42	    void start() {
 43	        var reservations = new InMemoryReservationRepository();
 44	        var messages = new InMemoryMessageRepository();
 45	        var service = new ReservationService(reservations, new ConfirmationMailer(messages));
 46	        List<Report<?>> reports = List.of(new OccupancyReport(reservations), new RevenueReport(reservations),
 47	                new TourismTaxReport(reservations, new BigDecimal("4.50")), new RatePlanReport(reservations));
 48	        app = Api.create(service, messages, reports).start(0);
 49	        base = "http://localhost:" + app.port();
 50	    }
 51	
 52	    @AfterEach
 53	    void stop() {
 54	        app.stop();
 55	    }
 56	
 57	    private HttpResponse<String> call(String method, String path, String body) throws Exception {
 58	        var b = HttpRequest.newBuilder(URI.create(base + path))
 59	                .method(method, body == null ? HttpRequest.BodyPublishers.noBody()
 60	                        : HttpRequest.BodyPublishers.ofString(body));
 61	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 62	    }
 63	
 64	    private String reserve(int room, String in, String out, int guests, String plan) {
 65	        return """
 66	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@x.com","guestCpf":"111.222.333-44",
 67	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
 68	    }
 69	
 70	    @Test
 71	    void highSeasonPricing() {
 72	        var q = Pricing.quote(RoomCatalog.require(101), LocalDate.parse("2027-07-10"),
 73	                LocalDate.parse("2027-07-12"), RatePlan.STANDARD);
 74	        assertEquals(Money.of("599.76"), q.total());
 75	        var nr = Pricing.quote(RoomCatalog.require(101), LocalDate.parse("2027-07-10"),
 76	                LocalDate.parse("2027-07-12"), RatePlan.NON_REFUNDABLE);
 77	        assertEquals(Money.of("89.96"), nr.discount());
 78	        assertEquals(Money.of("509.80"), nr.total());
 79	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
 80	        assertTrue(!Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
 81	    }
 82	
 83	    @Test
 84	    void fullFlowReceiptEmailAndReports() throws Exception {
 85	        var created = call("POST", "/reservations", reserve(201, "2027-03-10", "2027-03-12", 2, "STANDARD"));
 86	        assertEquals(201, created.statusCode());
 87	        JsonNode r = json.readTree(created.body());
 88	        assertEquals(1, r.get("id").asInt());
 89	        assertEquals("PENDING", r.get("status").asText());
 90	        assertEquals(779.80, r.get("total").asDouble());
 91	
 92	        assertEquals(404, call("GET", "/reservations/9", null).statusCode());
 93	        assertEquals(409, call("GET", "/reservations/1/document", null).statusCode());
 94	        assertEquals(409, call("POST", "/reservations/1/check-in", null).statusCode());
 95	        assertEquals(409, call("POST", "/reservations", reserve(201, "2027-03-11", "2027-03-13", 2, "STANDARD")).statusCode());
 96	        assertEquals(422, call("POST", "/reservations", reserve(101, "2027-03-11", "2027-03-13", 3, "STANDARD")).statusCode());
 97	        assertEquals(400, call("POST", "/reservations", "{oops").statusCode());
 98	        assertEquals(404, call("POST", "/reservations", reserve(999, "2027-03-11", "2027-03-13", 1, "STANDARD")).statusCode());
 99	
100	        assertEquals(200, call("POST", "/reservations/1/confirmation", null).statusCode());
101	        JsonNode msgs = json.readTree(call("GET", "/messages", null).body());
102	        assertEquals("Reserva confirmada - Pousada Maré Alta", msgs.get(0).get("subject").asText());
103	        assertEquals("""
104	                Olá, Carla Dias!
105	
106	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
107	
108	                Comprovante de reserva nº 1
109	                Hóspede: Carla Dias (CPF 111.222.333-44)
110	                Quarto: 201 (DELUXE)
111	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
112	                Diárias: R$ 779,80
113	                Total: R$ 779,80
114	
115	                A entrada é a partir das 14h, e a saída, até as 12h.
116	                Até breve!""", msgs.get(0).get("body").asText());
117	
118	        var occ = call("GET", "/reports/occupancy?date=2027-03-11", null);
119	        assertTrue(occ.headers().firstValue("content-type").orElse("").contains("text/csv"));
120	        assertEquals("Pousada Maré Alta,occupancy,2027-03-11\nroom,type,reservation,check_in,check_out\n"
121	                + "201,DELUXE,1,2027-03-10,2027-03-12\ntotal,1/5\n", occ.body());
122	        assertEquals("total,0/5", lastLine(call("GET", "/reports/occupancy?date=2027-03-12", null).body()));
123	
124	        assertEquals(200, call("POST", "/reservations/1/cancellation", null).statusCode());
125	        JsonNode cancelled = json.readTree(call("GET", "/reservations/1", null).body());
126	        assertEquals(779.80, cancelled.get("refund").asDouble());
127	        assertEquals("total,0.00", lastLine(call("GET", "/reports/revenue?month=2027-03", null).body()));
128	        assertEquals(400, call("GET", "/reports/revenue?month=2027-3", null).statusCode());
129	    }
130	
131	    @Test
132	    void nonRefundableCancelledStillCountsAndTaxAndPlans() throws Exception {
133	        call("POST", "/reservations", reserve(101, "2027-07-10", "2027-07-13", 2, "NON_REFUNDABLE"));
134	        call("POST", "/reservations", reserve(102, "2027-07-11", "2027-07-12", 1, "STANDARD"));
135	        call("POST", "/reservations/1/confirmation", null);
136	        call("POST", "/reservations/1/cancellation", null);
137	        call("POST", "/reservations/2/confirmation", null);
138	        call("POST", "/reservations/2/check-in", null);
139	        var out = json.readTree(call("POST", "/reservations/2/check-out", null).body());
140	        assertEquals("Comprovante de reserva", out.get("title").asText());
141	        assertEquals(299.88, call("GET", "/reservations/2/document", null).body().isEmpty() ? 0 : out.get("total").asDouble());
142	
143	        assertEquals("""
144	                Pousada Maré Alta,rate-plans,2027-07
145	                rate_plan,reservations,amount
146	                STANDARD,1,299.88
147	                NON_REFUNDABLE,1,764.69
148	                total,2,1064.57
149	                """, call("GET", "/reports/rate-plans?month=2027-07", null).body());
150	        // 2 hóspedes x 3 noites x 4,50 = 27,00 (reserva 1 está cancelada e não conta) ; reserva 2: 1x1x4,50
151	        assertEquals("""
152	                Pousada Maré Alta,tourism-tax,2027-07
153	                reservation,room,check_in,check_out,guests,nights,tax
154	                2,102,2027-07-11,2027-07-12,1,1,4.50
155	                total,4.50
156	                """, call("GET", "/reports/tourism-tax?month=2027-07", null).body());
157	    }
158	
159	    private static String lastLine(String csv) {
160	        String[] lines = csv.split("\n");
161	        return lines[lines.length - 1];
162	    }
163	}

